document.addEventListener('change',async event=>{
  try{
    if(event.target.id==='energy-mode')edit('settings','mode',{value:event.target.value},'Your pace is set.');
    if(event.target.id==='timer-duration'){timer.duration=Number(event.target.value);timer.remaining=timer.duration*60;timer.end=0;saveTimer();updateTimer();}
    if(event.target.id==='vault-category'){category=event.target.value;render();}
    if(event.target.id==='history-month'){historyMonth=event.target.value||today().slice(0,7);$('#month-history').innerHTML=historyHTML();}
    if(event.target.id==='goal-tracking'){const tracking=event.target.value;$('#manual-fields').hidden=tracking!=='manual';$('#target-fields').hidden=tracking!=='target';}
    if(event.target.id==='goal-chart-metric'){goalChartMetric=event.target.value;render();}
    if(event.target.id==='goal-chart-scope'){goalChartScope=event.target.value;render();}
    if(event.target.id==='goal-filter'){goalFilter=event.target.value;render();}
    if(event.target.id==='chart-period'){chartPeriod=event.target.value;render();}
    if(event.target.id==='chart-month'){chartMonth=event.target.value||today().slice(0,7);render();}
    if(event.target.id==='calendar-month'){calendarMonth=event.target.value||today().slice(0,7);render();}
    if(event.target.id==='routine-week'){routineWeek=event.target.value||today();render();$('#main .routines-card details').open=true;}
    if(event.target.id==='legacy-filter')legacyModal(event.target.value);
    if(event.target.id==='import-file'){
      const file=event.target.files[0];if(!file)return;if(file.size>8000000)throw new Error('Choose a backup smaller than 8 MB.');
      const incoming=importFile(await file.text(),device);validateState(incoming);
      const existing=makeBackup(state);const merged=mergeStates(state,incoming);
      modal('Your import is ready.', 'Your current records will be kept. Matching records use the most recent edit. A backup of the current data will download before merging.', `<p class="modal-subtitle">${Object.keys(incoming.tasks).length} priorities · ${Object.keys(incoming.notes).length} notes · ${Object.keys(incoming.legacy).length} preserved legacy records</p><div class="modal-actions"><button class="button subtle" data-action="close">Cancel</button><button class="button" id="confirm-import">Back up & merge</button></div>`);
      $('#confirm-import').addEventListener('click',()=>{const wasLocked=recoveryLocked;try{if(wasLocked)download({current:localStorage.getItem(STORAGE_KEY),legacy:localStorage.getItem('governor-data')},`governor-original-storage-${today()}.json`);download(existing,`governor-before-import-${today()}.json`);recoveryLocked=false;write(mergeStates(state,merged));closeModal();toast('Import merged. Original and current records are preserved.');}catch(error){recoveryLocked=wasLocked;toast(error.message);}});
    }
  }catch(error){toast(error.message);}
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;const formId=form.getAttribute('id');const f=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type=submit]');
  if(submit)submit.disabled=true;
  try {
    if(['task-form','note-form','goal-form'].includes(formId)&&!f.title.trim())throw new Error('Give this a short, concrete name.');
    if(formId==='weekly-form'&&!f.wins.trim())throw new Error('Write one observation from this week. A difficult week is worth recording too.');
    switch(formId){
      case 'area-form': {const title=f.title.trim();if(!title)throw new Error('Give your area a name.');const areas=mainAreas(),old=areas.find(area=>area.id===f.id);if(areas.some(area=>area.id!==f.id&&area.title.toLowerCase()===title.toLowerCase()))throw new Error('This area already exists. Edit or restore it in Manage areas.');const topic=old?.topic||areaTopics().find(topic=>topic.toLowerCase()===title.toLowerCase())||title;if(!old&&areas.some(area=>area.topic===topic))throw new Error('This topic already has an area. Edit or restore that shortcut.');const id=old?.id||`main-area-${uid()}`;edit('settings',id,{kind:'main-area',deleted:false,title,topic,topicLabel:title,icon:AREA_ICONS[f.icon]?f.icon:'4',visible:old?.visible!==false,order:old?.order??Math.max(-1,...areas.map(area=>area.order||0))+1},'Area saved.');areasModal();break;}
      case 'task-form': {const id=f.id||(f.capture?`capture-task-${f.capture}`:uid()), old=state.tasks[id], date=f.date||today();const parked=f.parked==='1'||!!old?.paused;const count=dailyTasks(state,date).filter(t=>!t.done&&!t.paused&&!t.carriedTo&&t.id!==id).length;if(!parked&&(!old||old.date!==date)&&count>=(date===today()?taskLimit(state):3))throw new Error('This day already has enough priorities. Choose another day or park an action first.');if(f.capture&&old&&!old.deleted)throw new Error('This thought already has a priority. Edit that priority instead.');if(f.goal&&(!state.goals[f.goal]||state.goals[f.goal].deleted&&old?.goal!==f.goal))throw new Error('Choose an existing plan or Other.');const values={deleted:false,minutes:Number(f.minutes)||0,title:f.title.trim(),action:f.action.trim()||f.title.trim(),goal:f.goal,date,done:old?.done||false,paused:parked,order:old?.order??count};if(old&&!old.deleted&&old.date!==date){const next=structuredClone(state);const carried=carryTask(next,id,date,device,values);if(parked)put(next,'tasks',carried.id,{paused:true},device);write(next);toast('Rescheduled. Earlier records retained.');}else edit('tasks',id,values,'Priority saved.');if(f.capture){const next=structuredClone(state);put(next,'captures',f.capture,{archived:true},device);write(next);}closeModal();break;}
      case 'parked-focus-form': {const next=structuredClone(state);focusParked(next,new FormData(event.target).getAll('tasks'),device);write(next);closeModal();toast('Your next priorities are in focus. Parked work stays saved.');break;}
      case 'search-form': case 'top-search': searchModal(f.query||'');break;
      case 'inline-capture': case 'capture-form': {const text=f.text.trim();if(!text)throw new Error('Write a thought first.');edit('captures',f.id||uid(),{text,date:state.captures[f.id]?.date||today(),archived:state.captures[f.id]?.archived||false},'Thought saved. Back to your next action.',{redraw:false});localStorage.removeItem('governor.capture.draft');if($('#capture-text'))$('#capture-text').value='';if(formId==='capture-form')closeModal();else form.reset();break;}
      case 'checkin-form': edit('checkins',f.id,{date:today(),note:f.note.trim(),energy:f.energy},'Today’s check-in saved.');closeModal();break;
      case 'weekly-form': {const id=f.id||uid();edit('reviews',id,{date:state.reviews[id]?.date||today(),wins:f.wins.trim(),obstacles:f.obstacles.trim(),next:f.next.trim(),period:f.period||'week',archived:false},'Weekly review saved. One adjustment at a time.');closeModal();break;}
      case 'goal-form': {if(f.tracking==='target'&&!(Number(f.target)>0))throw new Error('Set a target greater than zero.');const values={horizon:f.horizon,startDate:f.startDate,title:f.title.trim(),subtitle:f.subtitle.trim(),outcome:f.outcome.trim(),milestone:f.milestone.trim(),evidence:f.evidence.trim(),status:f.status,tracking:f.tracking,progress:Number(f.progress),current:Number(f.current),target:Number(f.target),unit:f.unit.trim(),deadline:f.deadline,nextAction:f.nextAction.trim(),deleted:false};for(const n of [1,2,3]){values[`month${n}`]=f[`month${n}`].trim();values[`month${n}Done`]=f[`month${n}Done`]==='on';values[`month${n}Date`]=f[`month${n}Date`];values[`month${n}Evidence`]=f[`month${n}Evidence`].trim();}changeGoal(f.id||uid(),values,'Goal and progress saved.');closeModal();break;}
      case 'plan-form': if(f.start&&f.horizon&&f.horizon<f.start)throw new Error('The planning horizon must be on or after the sprint start.');edit('settings','plan',f,'Your direction is saved.');closeModal();break;
      case 'note-form': {if(f.url&&!safeURL(f.url))throw new Error('Use a link beginning with https:// or http://.');const next=structuredClone(state), id=f.id||(f.capture?`capture-note-${f.capture}`:uid());const fields={tags:f.tags.trim(),goal:f.goal,title:f.title.trim(),category:f.category,body:f.body.trim(),url:f.url.trim(),entryType:f.entryType||'note',archived:state.notes[id]?.archived||false};if(f.entryType==='book'){fields.author=f.author.trim();fields.readingStatus=f.readingStatus;fields.pagesRead=Number(f.pagesRead);fields.pagesTotal=Number(f.pagesTotal);if(fields.pagesTotal>0&&fields.pagesRead>fields.pagesTotal)throw new Error('Pages read cannot exceed total pages.');}if(f.entryType==='routine')fields.routineTarget=Number(f.routineTarget);put(next,'notes',id,fields,device);if(f.capture)put(next,'captures',f.capture,{archived:true},device);write(next);closeModal();toast('Saved in the Vault.');break;}
      case 'cloud-config-form': if(cloud.session)throw new Error('Sign out before changing your cloud project.');saveConfig(f.url.trim(),f.key.trim());cloud.config=loadConfig();cloud.lastError='';settingsModal();toast('Connection saved. Sign in to enable cloud sync.');break;
      case 'cloud-signin-form': await cloud.sendLink(f.email.trim());$('#cloud-message').textContent='Check your email. Open the sign-in link on this device. If there is no email, check spam and the project’s email limits.';break;
      case 'cloud-password-form': await cloud.signInPassword(f.email.trim(),f.password);form.reset();await cloud.sync();settingsModal();toast(cloud.lastError||'Signed in to your separate account workspace. Sync status shows whether upload succeeded.');break;
    }
  }catch(error){const target=$('#form-error')||$('#cloud-message');if(target)target.textContent=error.message;else toast(error.message);}
  finally{if(submit?.isConnected)submit.disabled=false;}
});
window.addEventListener('storage',event=>{if(localStorage.getItem(PROFILE_KEY)!==boundProfile){cloud.dispose();location.reload();return;}if(event.key==='governor.cloud.session.v1'){cloud.dispose();location.reload();return;}if(event.key===STORAGE_KEY&&event.newValue){if(profileCopy(boundProfile)!==event.newValue)return;try{const merged=mergeStates(state,JSON.parse(event.newValue));if(JSON.stringify(merged)!==JSON.stringify(state))write(merged);else{state=merged;render();}}catch{toast('Another tab contains unreadable data. Your open copy is preserved.');}}});
