function timerText(){const seconds=timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining;return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function updateTimer(){if(timer.end&&timer.end<=Date.now()){timer.end=0;timer.remaining=0;saveTimer();toast('Focus time is complete. Take a breath and choose what’s next.');}if($('#timer-display'))$('#timer-display').textContent=timerText();if($('#timer-toggle'))$('#timer-toggle').textContent=timer.end?'Pause':'Start Focus Session';if($('#timer-duration'))$('#timer-duration').disabled=!!timer.end;}
setInterval(updateTimer,1000);setInterval(()=>{if(!document.hidden)cloud.sync();},60000);
render();if(startupMessage)toast(startupMessage);
