if(!document.documentElement.hasAttribute('data-portable') && 'serviceWorker' in navigator && (location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))){
  // Public assets are one versioned release. A completed update never clears user storage.
  navigator.serviceWorker.addEventListener('controllerchange',()=>{
    const channel=new MessageChannel();
    channel.port1.onmessage=event=>{
      channel.port1.close();
      if(event.data?.release===document.querySelector('meta[name="governor-release"]')?.content)return;
      const editing=$('#modal')?.open || /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');
      if(!editing)location.reload();
      else {toast('Your app update is ready. Save this edit, then open the update link in Settings.');}
    };
    navigator.serviceWorker.controller?.postMessage({type:'GOVERNOR_VERSION'},[channel.port2]);
  });
  navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{
    if(navigator.onLine)toast('Offline installation failed. Your saved data remains on this device; retry online using the update link in Settings.');
  });
}
